import{_ as e,o as s,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"21. Understanding Memory Layout (Stack, Heap, Data, Code)","description":"The Little Book of C — 21. Understanding Memory Layout (Stack, Heap, Data, Code)","frontmatter":{"title":"21. Understanding Memory Layout (Stack, Heap, Data, Code)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working with Memory"],"description":"The Little Book of C — 21. Understanding Memory Layout (Stack, Heap, Data, Code)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":21,"sidebarWeight":21,"lang":"en-US","alternateEn":"/posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code)","alternateZh":"/posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code)"},"headers":[],"relativePath":"posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code).md","filePath":"posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code).md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/03-Working with Memory/021-Understanding Memory Layout (Stack, Heap, Data, Code).md"};function o(l,a,r,d,p,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/03-内存/021-Understanding Memory Layout (Stack, Heap, Data, Code))</p><p>Before you can master pointers or dynamic memory, you need to understand how memory is organized in a running C program. C gives you a level of control that few languages allow, but to use it safely, you must know where your data lives and how long it stays there.</p><h4 id="the-memory-segments" tabindex="-1">The Memory Segments <a class="header-anchor" href="#the-memory-segments" aria-label="Permalink to &quot;The Memory Segments&quot;">​</a></h4><p>When a program runs, its memory is divided into several key sections:</p><table tabindex="0"><thead><tr><th>Segment</th><th>Purpose</th><th>Example Data</th></tr></thead><tbody><tr><td>Code (Text)</td><td>Stores compiled machine instructions</td><td>Functions, program logic</td></tr><tr><td>Data (Static)</td><td>Stores global and static variables with initialized values</td><td><code>int count = 5;</code></td></tr><tr><td>BSS (Uninitialized Data)</td><td>Holds global/static variables that start as zero or are uninitialized</td><td><code>int buffer[256];</code></td></tr><tr><td>Heap</td><td>Used for dynamic memory allocation (<code>malloc</code>,<code>calloc</code>)</td><td>Large, runtime-created data</td></tr><tr><td>Stack</td><td>Stores local variables, function parameters, return addresses</td><td>Function calls, recursion</td></tr></tbody></table><p>These segments are managed differently by the operating system, and each has a different lifetime and scope.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a small program that prints the memory addresses of different variables to show where they live:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>// Global variable (Data segment)</span></span>
<span class="line"><span>int global_var = 42;</span></span>
<span class="line"><span>// Uninitialized global variable (BSS segment)</span></span>
<span class="line"><span>int global_bss;</span></span>
<span class="line"><span>void show_addresses(void) {</span></span>
<span class="line"><span>    // Local variable (Stack)</span></span>
<span class="line"><span>    int local_var = 10;</span></span>
<span class="line"><span>    // Static variable (Data segment)</span></span>
<span class="line"><span>    static int static_var = 20;</span></span>
<span class="line"><span>    // Dynamic variable (Heap)</span></span>
<span class="line"><span>    int *heap_var = malloc(sizeof(int));</span></span>
<span class="line"><span>    *heap_var = 30;</span></span>
<span class="line"><span>    printf(&quot;Code (function) address:     %p\\n&quot;, (void *)show_addresses);</span></span>
<span class="line"><span>    printf(&quot;Global variable address:     %p\\n&quot;, (void *)&amp;global_var);</span></span>
<span class="line"><span>    printf(&quot;Uninitialized global address:%p\\n&quot;, (void *)&amp;global_bss);</span></span>
<span class="line"><span>    printf(&quot;Static variable address:     %p\\n&quot;, (void *)&amp;static_var);</span></span>
<span class="line"><span>    printf(&quot;Stack variable address:      %p\\n&quot;, (void *)&amp;local_var);</span></span>
<span class="line"><span>    printf(&quot;Heap variable address:       %p\\n&quot;, (void *)heap_var);</span></span>
<span class="line"><span>    free(heap_var);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    show_addresses();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc memory_layout.c -o memory_layout</span></span>
<span class="line"><span>./memory_layout</span></span></code></pre></div><p>Example output (addresses vary by system):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Code (function) address:     0x561ce7348169</span></span>
<span class="line"><span>Global variable address:     0x561ce7546014</span></span>
<span class="line"><span>Uninitialized global address:0x561ce7546018</span></span>
<span class="line"><span>Static variable address:     0x561ce7546020</span></span>
<span class="line"><span>Stack variable address:      0x7ffc94b65a5c</span></span>
<span class="line"><span>Heap variable address:       0x561ce774b2a0</span></span></code></pre></div><p>Notice how the stack address is much higher than the heap, the stack usually grows downward, and the heap grows upward in memory.</p><h4 id="how-it-all-works" tabindex="-1">How It All Works <a class="header-anchor" href="#how-it-all-works" aria-label="Permalink to &quot;How It All Works&quot;">​</a></h4><p>Code segment</p><ul><li>Contains compiled instructions.</li><li>Usually marked as read-only to prevent accidental modification.</li></ul><p>Data segment</p><ul><li>Holds global and static variables initialized with values.</li><li>Exists for the entire program duration.</li></ul><p>BSS (Block Started by Symbol)</p><ul><li>Holds uninitialized global/static variables.</li><li>Automatically zero-initialized at runtime.</li></ul><p>Stack</p><ul><li>Used for local variables and function calls.</li><li>Automatically managed, grows and shrinks as functions are called and return.</li></ul><p>Heap</p><ul><li>Allocated manually at runtime.</li><li>Requires explicit management (<code>malloc</code> and<code>free</code>).</li></ul><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Every time you write a variable, you’re deciding, whether consciously or not, where in memory it lives. Understanding this layout helps you:</p><ul><li>Debug memory errors (segmentation faults, leaks, corruption).</li><li>Reason about performance and function calls.</li><li>Write correct code when using<code>malloc</code>,<code>free</code>, and pointers.</li><li>Build real systems software like allocators or kernels.</li></ul><p>Without this mental model, C memory bugs feel mysterious; with it, they become logical and fixable.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Add more global, local, and static variables to the example and print their addresses.</li><li>Allocate two blocks with<code>malloc()</code> and compare their addresses, the heap grows upward.</li><li>Call<code>show_addresses()</code> multiple times and notice how the stack variable’s address changes each call.</li><li>Move a variable from global to local and observe how its memory segment changes.</li><li>Draw a diagram showing stack, heap, data, and code regions for your system.</li></ol><p>Understanding memory layout is your first real step into systems-level C, it’s how you begin to see your code not just as text, but as structured bytes living inside memory.</p>`,32)])])}const h=e(i,[["render",o]]);export{m as __pageData,h as default};
